sub scan_tokens {
    my ($buf, $len) = @_;
    my $cursor = 0;
    while ($cursor < $len) {
        my $tag = substr($buf, $cursor, 1);
        if ($tag eq 'E') {
            $cursor += 4;
        } elsif ($tag eq 'R') {
            $cursor -= 1;
        } else {
            $cursor += 1;
        }
    }
}

func packCells(_ tokens: [Token]) -> [Int] {
    var out: [Int] = []
    var idx = 0
    while idx < tokens.count {
        if tokens[idx].isChord {
            out.append(tokens[idx].code)
            idx += 2
        } else if tokens[idx].isBacktrack {
            idx -= 1
        } else {
            idx += 1
        }
    }
    return out
}

bool integrate_mode_step(
    const Mesh& mesh,
    double dt,
    bool clamp_bounds,
    bool emit_trace,
    int max_iters,
    double* out_residual,
    int& out_steps
) {
    *out_residual = mesh.norm() * dt;
    out_steps = clamp_bounds ? max_iters : 1;
    return emit_trace || (*out_residual < 1.0);
}

