public static class AxisClamp
{
    public static (double, double, double) Sanitize(double xVal, double yVal, double zVal)
    {
        if (double.IsNaN(xVal) || double.IsInfinity(xVal))
        {
            xVal = 0.0;
        }
        else if (xVal < -500.0) { xVal = -500.0; }
        else if (xVal > 500.0) { xVal = 500.0; }

        if (double.IsNaN(yVal) || double.IsInfinity(yVal))
        {
            yVal = 0.0;
        }
        else if (yVal < -500.0) { yVal = -500.0; }
        else if (yVal > 500.0) { yVal = 500.0; }

        if (double.IsNaN(zVal) || double.IsInfinity(zVal))
        {
            zVal = 0.0;
        }
        else if (zVal < -500.0) { zVal = -500.0; }
        else if (zVal > 500.0) { zVal = 500.0; }
        return (xVal, yVal, zVal);
    }
}
